	\begin{tikzpicture}[
	scale=1.3,
	grow = right,
	edge from parent/.style = {draw, color=deepskyblue, thick, -latex},
	every node/.style = {font=\small, black},
	]
	\node[] (R) {$f(x,y)$}
	child {
		node[bag] (B) {$y(s)$}        
		child {
			node[bag, label={right=5pt: \footnotesize $\dfrac{\partial f}{\partial y}\cdot \dfrac{\textrm{d} y}{\textrm{d} s}$}
			] (BB) {$s$}
			edge from parent node[edge, below] {$\dfrac{\textrm{d} y}{\textrm{d} s}$}
		}
		edge from parent node[edge, below left] {$\dfrac{\partial f}{\partial y}$}
	}
	child {
		node[bag] (T) {$x(s)$}        
		child {
			node[bag, label={right=5pt: \footnotesize $\dfrac{\partial f}{\partial x}\cdot \dfrac{\textrm{d} x}{\textrm{d} s}$}
			] (TB) {$s$}
			edge from parent node[edge, above] {$\dfrac{\textrm{d} x}{\textrm{d} s}$}
		}
		edge from parent node[edge, above left] {$\dfrac{\partial f}{\partial x}$}
	};

	%                                              TT(top top)
	%                                        <                  
